mapper.select:
SELECT id, task_id taskId, keyword, user_prompt userPrompt, draft_content draftContent, ai_name aiName, DATE_FORMAT(create_time, '%Y-%c-%d %H:%i:%s') createTime, share_url shareUrl, share_img_url shareImgUrl, is_push isPush FROM wc_playwright_draft WHERE user_name = #{userId}
AND ai_name = #{aiName}
AND (keyword LIKE CONCAT('%', #{keyword}, '%') OR user_prompt LIKE CONCAT('%', #{keyword}, '%') OR draft_content LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY create_time DESC
